def largest_smallest_integers(lst):
    # Convert list to integers
    ints = [int(x) for x in lst]

    # Find the largest negative integer
    negative_integers = [x for x in ints if x < 0]
    if negative_integers:
        a = max(negative_integers)
    else:
        a = None

    # Find the smallest positive integer
    positive_integers = [x for x in ints if x > 0]
    if positive_integers:
        b = min(positive_integers)
    else:
        b = None

    return (a, b)
