def largest_prime_factor(n: int):
    """Return the largest prime factor of n. Assume n > 1 and is not a prime.
    >>> largest_prime_factor(13195)
    29
    >>> largest_prime_factor(2048)
    2
    """
    if n <= 1:
        raise ValueError("n must be greater than 1")

    if n == 1:
        return 1
    if n == 2:
        return 2

    # Check for small factors
    i = 2
    while i * i <= n:
        if n % i == 0:
            # Found a factor
            temp_n = n
            while temp_n % i == 0:
                temp_n //= i
            # Check if i is prime
            if i == 2:
                return i
            if i > 2:
                # Check if i is prime
                is_prime = True
                for j in range(2, int(i ** 0.5) + 1):
                    if temp_n % j == 0:
                        is_prime = False
                        break
                if is_prime:
                    return i
            break
        i += 1

    # If no small factors found, the largest prime factor is n itself
    return n
```

